import 'package:flutter/material.dart';

/// Text-first blog reader. Image tokens are generated by the Super Admin
/// composer and never interpreted as HTML/scripts.
class BlogArticleBody extends StatelessWidget {
  const BlogArticleBody({required this.content, super.key});

  final String content;

  static final _image = RegExp(r'^!\[([^\]]*)\]\((https://[^\s)]+)\)$');

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final blocks = <Widget>[];
    for (final rawLine in content.split('\n')) {
      final line = rawLine.trim();
      if (line.isEmpty) {
        blocks.add(const SizedBox(height: 10));
        continue;
      }
      final photo = _image.firstMatch(line);
      if (photo != null) {
        final uri = Uri.tryParse(photo.group(2)!);
        if (uri?.scheme == 'https' && uri?.host.isNotEmpty == true) {
          blocks.add(Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              ClipRRect(
                borderRadius: BorderRadius.circular(16),
                child: Image.network(
                  uri.toString(),
                  fit: BoxFit.contain,
                  errorBuilder: (_, _, _) => const SizedBox.shrink(),
                ),
              ),
              if (photo.group(1)!.isNotEmpty)
                Padding(
                  padding: const EdgeInsets.only(top: 5),
                  child: Text(photo.group(1)!, style: theme.textTheme.bodySmall),
                ),
            ],
          ));
        }
        continue;
      }
      if (line.startsWith('## ')) {
        blocks.add(Text(line.substring(3), style: theme.textTheme.titleMedium));
      } else if (line.startsWith('# ')) {
        blocks.add(Text(line.substring(2), style: theme.textTheme.titleLarge));
      } else {
        blocks.add(SelectableText(
          line,
          style: theme.textTheme.bodyLarge?.copyWith(height: 1.75),
        ));
      }
    }
    return Padding(
      padding: const EdgeInsets.only(top: 18),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: blocks,
      ),
    );
  }
}
